let confirmModalResolveCallback=null;function showConfirmDialog(o,n="Подтверждение"){return new Promise((l=>{const e=document.getElementById("confirm-modal"),t=document.getElementById("confirm-title"),c=document.getElementById("confirm-message");if(!e||!t||!c)return console.error("Confirm dialog elements not found in DOM"),void l(confirm(o));t.textContent=n,c.textContent=o,confirmModalResolveCallback=l,e.showModal()}))}function confirmModalResolve(o){const n=document.getElementById("confirm-modal");n&&n.close(),confirmModalResolveCallback&&(confirmModalResolveCallback(o),confirmModalResolveCallback=null)}function getConfirmDialogHTML(){return'\n\x3c!-- Custom Confirmation Dialog --\x3e\n<dialog id="confirm-modal" class="modal">\n    <div class="modal-box max-w-lg">\n        <h3 class="font-bold text-lg mb-4" id="confirm-title">Подтверждение</h3>\n        <p class="whitespace-pre-line mb-6" id="confirm-message"></p>\n        <div class="modal-action">\n            <button type="button" class="btn btn-ghost" onclick="confirmModalResolve(false)">Отмена</button>\n            <button type="button" class="btn btn-error" onclick="confirmModalResolve(true)">Подтвердить</button>\n        </div>\n    </div>\n    <form method="dialog" class="modal-backdrop">\n        <button onclick="confirmModalResolve(false)">close</button>\n    </form>\n</dialog>\n'}